input.command:
# Extract text from recent daily reports for format reference
$docs = @(
  "E:\project\日报\工作日报-2026-08-04.docx",
  "E:\project\日报\工作日报-2026-08-03.docx",
  "E:\project\日报\工作日报-2026-07-31.docx",
  "E:\project\日报\工作日报-2026-07-30.docx"
)
Add-Type -AssemblyName System.IO.Compression.FileSystem
foreach ($doc in $docs) {
  Write-Host "======== $(Split-Path $doc -Leaf) ========"
  try {
    $zip = [System.IO.Compression.ZipFile]::OpenRead($doc)
    $entry = $zip.Entries | Where-Object { $_.FullName -eq 'word/document.xml' }
    $stream = $entry.Open()
    $reader = New-Object System.IO.StreamReader($stream)
    $xml = $reader.ReadToEnd()
    $reader.Close(); $stream.Close(); $zip.Dispose()
    $text = [regex]::Replace($xml, '</w:p>', "`n")
    $text = [regex]::Replace($text, '<[^>]+>', '')
    $text = [System.Net.WebUtility]::HtmlDecode($text)
    Write-Host $text
  } catch {
    Write-Host "Error: $_"
  }
  Write-Host ""
}
